//  ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================
function getCharsForLevel(level) {
    var count = 6;
    var start = ((level - 1) * count) % DB.length;
    var chars = [];
    for (var i = 0; i < count; i++) {
        var idx = (start + i) % DB.length;
        var item = DB[idx];
        chars.push({
            h: item[0],
            p: item[1],
            r: item[2],
            e: item[3] || '🀄',
            c: i % 6
        });
    }
    return chars;
}

function getAllWords() {
    var result = [];
    for (var i = 0; i < DB.length; i++) {
        var words = DB[i][4];
        for (var j = 0; j < words.length; j++) {
            result.push({
                hz: words[j][0],
                py: words[j][1],
                ru: words[j][2]
            });
        }
    }
    return result;
}

function findChar(char) {
    for (var i = 0; i < DB.length; i++) {
        if (DB[i][0] === char) return DB[i];
    }
    return null;
}

function getRandomChars(count) {
    count = count || 6;
    var shuffled = DB.slice();
    for (var i = shuffled.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var temp = shuffled[i];
        shuffled[i] = shuffled[j];
        shuffled[j] = temp;
    }
    return shuffled.slice(0, count);
}

